import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/outlierr/2023_no2.csv')
adj_df = pd.read_csv(ADJACENCY_PATH)

# Prepare adjacency dictionary
adjacency = {}
for borough in df['borough'].unique():
    neighbors = adj_df[adj_df['borough'] == borough]['neighbor'].tolist()
    adjacency[borough] = neighbors

# Initialize variables
no2_values = df.set_index('borough')['NO2_value'].to_dict()
boroughs = list(no2_values.keys())
n = len(boroughs)

# Iterative-R method implementation
def iterative_r_outlier_detection(values, adjacency, max_iter=10, threshold=2.5):
    residuals = {}
    standardized = {}

    for _ in range(max_iter):
        # Calculate neighborhood averages
        neighborhood_avgs = {}
        for borough in boroughs:
            neighbors = adjacency.get(borough, [])
            if neighbors:
                neighbor_values = [values[n] for n in neighbors if n in values]
                neighborhood_avgs[borough] = np.mean(neighbor_values) if neighbor_values else np.nan
            else:
                neighborhood_avgs[borough] = np.nan

        # Calculate global regression (borough value vs neighborhood average)
        valid_pairs = [(values[b], neighborhood_avgs[b]) for b in boroughs 
                      if not np.isnan(neighborhood_avgs[b])]
        if len(valid_pairs) < 2:
            break

        y, x = zip(*valid_pairs)
        slope, intercept = np.polyfit(x, y, 1)

        # Calculate residuals
        for borough in boroughs:
            if borough in neighborhood_avgs and not np.isnan(neighborhood_avgs[borough]):
                predicted = intercept + slope * neighborhood_avgs[borough]
                residuals[borough] = values[borough] - predicted
            else:
                residuals[borough] = np.nan

        # Standardize residuals
        valid_residuals = [r for r in residuals.values() if not np.isnan(r)]
        if len(valid_residuals) > 1:
            mean_res = np.mean(valid_residuals)
            std_res = np.std(valid_residuals, ddof=1)
            for borough in boroughs:
                if not np.isnan(residuals[borough]):
                    standardized[borough] = (residuals[borough] - mean_res) / std_res
                else:
                    standardized[borough] = np.nan

        # Check for convergence (no new outliers)
        outliers = [b for b in boroughs 
                   if not np.isnan(standardized.get(b, np.nan)) 
                   and abs(standardized[b]) > threshold]
        if not outliers:
            break

    return standardized

# Run detection
standardized_residuals = iterative_r_outlier_detection(no2_values, adjacency)

# Get Merton's result
merton_z = standardized_residuals.get('Merton', np.nan)

# Determine final answer
if np.isnan(merton_z):
    print("FINAL ANSWER: NOT AN OUTLIER (z = nan)")
elif merton_z > 2.5:
    print(f"FINAL ANSWER: OUTLIER - HIGH (z = {merton_z})")
elif merton_z < -2.5:
    print(f"FINAL ANSWER: OUTLIER - LOW (z = {merton_z})")
else:
    print(f"FINAL ANSWER: NOT AN OUTLIER (z = {merton_z})")
